      'RespondScript {\r\n  Program = StateDeclaration* Default Statement*\r\n\r\n  Default = Display+\r\n \r\n  Statement = MethodCall\r\n            | ConditionalBlock\r\n            | RollDeclaration\r\n            | Display\r\n  \r\n // instead of assigning values, the State Declaration checks \r\n // which parts of the object state are actually relevant\r\n  StateDeclaration = ObjectState | PlayerState\r\n  \r\n  ObjectState = "{{#" listOf<Identifier, ","> "}}"\r\n  PlayerState = "{{P" PlayerStuff "}}"\r\n  PlayerStuff = "pockets" | "thoughts" \r\n \r\n  MethodCall = "{{&" listOf<Identifier, ","> "}}"\r\n  \r\n  ConditionalBlock = IfClause ElseIfClause* ElseClause? "{{/?}}"\r\n  IfClause         = "{{?" Condition "}}" Statement*\r\n  ElseIfClause     = "{{??" Condition "}}" Statement*\r\n  ElseClause       = "{{!?" "}}" Statement*\r\n\r\n  AliasBlock = "{{alias}}" AliasCase+ ElseClause? "{{/alias}}"\r\n  AliasCase  = "{{:" listOf<StringLiteral, ","> "}}" Statement*\r\n\r\n  Condition        = Identifier Comparator Value\r\n  Comparator       = "==" | "!=" | ">=" | "<=" | ">" | "<"\r\n  \r\n  EmbedState = "{{" IdentifierOperation "}}"\r\n  \r\n  IdentifierOperation = Identifier (Operand RightHandSide)?\r\n  RightHandSide = Identifier | NumberLiteral\r\n  Operand = "+" | "-" | "*" | "/"\r\n  \r\n  RollDeclaration = "{{@" NumberLiteral "|" listOf<Approach, ",">? "|" listOf<Skill, ",">? "}}" RollOutcome* "{{/@}}"\r\n  RollOutcome = (FlavorVariant? RollSucceed RollFail?)\r\n  \r\n  FlavorVariant = "{{>" Approach? "|"? Skill? "}}" // you can get an approach or a skill, or both!\r\n  RollSucceed = "{{=succeed}}" Statement*\r\n  RollFail = "{{=fail}}" Statement*\r\n  \r\n  Approach = caseInsensitive<"Careful"> \r\n           | caseInsensitive<"Clever"> \r\n           | caseInsensitive<"Flashy"> \r\n           | caseInsensitive<"Forceful"> \r\n           | caseInsensitive<"Quick"> \r\n           | caseInsensitive<"Sneaky"> \r\n           \r\n  Skill = caseInsensitive<"Homemaking">\r\n        | caseInsensitive<"Sustainment">\r\n        | caseInsensitive<"Skulduggery">\r\n        | caseInsensitive<"Scholarship">\r\n        | caseInsensitive<"Athletics">\r\n        | caseInsensitive<"Interfacing">\r\n        | caseInsensitive<"Composure">\r\n        | caseInsensitive<"Esthesia">\r\n        | caseInsensitive<"Instinct">\r\n        | caseInsensitive<"Dominion">\r\n  \r\n  Display = EmbedState | PlainText\r\n  \r\n  PlainText = (~"{{" any)+\r\n \r\n  Identifier = ~Keyword name\r\n  name = letter alnum*\r\n  \r\n  Keyword = ActionType | BooleanLiteral | "succeed" | "fail"\r\n\r\n  Value = StringLiteral | NumberLiteral | BooleanLiteral\r\n  StringLiteral = "\\"" (~"\\"" any)* "\\""\r\n  NumberLiteral = digit+\r\n  BooleanLiteral = "true" | "false"\r\n\r\n  ActionType = "dec" | "inc" | "set"\r\n             | "flip" | "true" | "untrue"\r\n                        \r\n  ActionDegree = StringLiteral | NumberLiteral\r\n  \r\n  space := "\\x00".."\\x20"\r\n}',
